      "id": 1,
      "claim": "Soil formation requires the addition of mineral particles and organic matter (humus) to create a new pedogenic medium.",
      "evidence": "Standard soil science definition: soil = weathered mineral fraction + organic fraction (humus).",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Biological decomposition of a log converts wood to humus on a timescale of months to a few years, producing a substantial amount of organic material quickly.",
      "evidence": "Field studies show mass loss of 30‑70 % in a year for small to medium logs in temperate forests; microbial activity accelerates breakdown.",
      "weight": 0.30,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Weathering of a static rock in a garden proceeds extremely slowly, on the order of 10⁻⁴–10⁻³ mm per year, yielding negligible mineral soil within human timeframes.",
      "evidence": "In‑situ rock weathering measurements report rates of 0.001–0.01 mm yr⁻¹.",
      "weight": 0.10,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Water running in a stream mainly transports pre‑existing sediment; deposition creates new soil layers but does not generate new material, and the net accumulation rate depends on upstream supply, often comparable to or slower than the organic input from a single rotting log.",
      "evidence": "Fluvial geomorphology texts describe streams as sediment conveyance systems; alluvial soil formation rates are limited by sediment load and can be <0.1 t m⁻² yr⁻¹ in many catchments.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "Waves breaking on a beach primarily erode and re‑work sand, preventing the stable buildup of nutrient‑rich soil.",
      "evidence": "Coastal studies show net sand loss or lateral transport with little long‑term organic accumulation.",
      "weight": 0.10,
      "depends_on": [1]
    },
    {
      "id": 6,
      "claim": "Comparing the rates, the rapid conversion of wood to humus by decomposition (log rotting) adds new soil material faster than the slow rock weathering, the transport‑limited deposition in streams, or the erosive wave action.",
      "evidence": "Step 2 shows organic mass addition of several tonnes per hectare per year, whereas steps 3‑5 contribute orders of magnitude less new material.",
      "weight": 0.10,
      "depends_on": [2, 3, 4, 5]
    }
